package com.example.newapp;
import android.app.Activity;import android.content.Intent;import android.os.Bundle;import android.widget.Button;import android.widget.LinearLayout;import android.widget.ScrollView;import android.widget.TextView;import com.google.zxing.integration.android.IntentIntegrator;import com.google.zxing.integration.android.IntentResult;import org.json.JSONObject;import java.text.SimpleDateFormat;import java.util.Date;import java.util.List;import java.util.Locale;
public class PriceHistoryScreen extends Activity {
 private StoreManagementRepository repo;private TextView status,results;private final SimpleDateFormat fmt=new SimpleDateFormat("dd/MM/yyyy HH:mm:ss",Locale.getDefault());private int dp(int v){return(int)(v*getResources().getDisplayMetrics().density+0.5f);}
 @Override protected void onCreate(Bundle b){super.onCreate(b);repo=new StoreManagementRepository(this);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(16),dp(16),dp(16),dp(16));TextView title=new TextView(this);title.setText("ค้นหาประวัติการแก้ไขราคา");title.setTextSize(21);root.addView(title);
 Button scan=new Button(this);scan.setText("สแกนบาร์โค้ดสินค้า");scan.setOnClickListener(v->new IntentIntegrator(this).setPrompt("สแกนบาร์โค้ดสินค้า 1 รายการ").setBeepEnabled(true).setOrientationLocked(true).initiateScan());root.addView(scan);status=new TextView(this);status.setText("สแกนบาร์โค้ดเพื่อค้นหาประวัติ");root.addView(status);ScrollView scroll=new ScrollView(this);results=new TextView(this);results.setTextSize(15);scroll.addView(results);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1f));Button back=new Button(this);back.setText("กลับ");back.setOnClickListener(v->finish());root.addView(back);setContentView(root);}
 @Override protected void onActivityResult(int req,int res,Intent data){IntentResult scan=IntentIntegrator.parseActivityResult(req,res,data);if(scan!=null){String code=scan.getContents();if(code==null||code.trim().isEmpty()){status.setText("ยกเลิกการสแกน");results.setText("");return;}List<JSONObject> list=repo.getPriceHistory(code);status.setText("บาร์โค้ด: "+code);if(list.isEmpty()){results.setText("ไม่พบประวัติการแก้ไขราคา");return;}StringBuilder out=new StringBuilder();for(JSONObject r:list){JSONObject p=r.optJSONObject("payload");if(p==null)continue;if(out.length()>0)out.append("\n\n");out.append("ชื่อสินค้า: ").append(p.optString("productName")).append("\n").append("บาร์โค้ด: ").append(p.optString("barcode")).append("\n").append("ราคาเดิม: ").append(p.opt("oldPrice")).append(" บาท\n").append("ราคาใหม่: ").append(p.opt("newPrice")).append(" บาท\n").append("วันเวลา: ").append(fmt.format(new Date(p.optLong("changedAt"))));}results.setText(out.toString());return;}super.onActivityResult(req,res,data);}
}
